function percentAgainst(current: number | null, comparison: number | null): number | null {
  if (current === null || comparison === null || comparison === 0) return null;
  return Number((((current - comparison) / comparison) * 100).toFixed(2));
}

export function applyDonMappings(assets: DemoAsset[]): DemoAsset[] {
  return assets.map((asset) => {
    if (asset.kind !== 'card' || asset.setCode !== 'DON') {
      return asset;
    }
    const mapping = donMappings[asset.id];
    if (!mapping) {
      return asset;
    }
    const trend = mapping.pricing.cardmarket.trend;
    return {
      ...asset,
      cardmarketProductId: mapping.cardmarketProductId,
      cardmarketExpansionId: mapping.cardmarketExpansionId,
      cardmarketPriceState: mapping.cardmarketPriceState,
      cardmarketPriceReason: mapping.cardmarketPriceReason,
      cardmarketMappingEvidence: mapping.cardmarketMappingEvidence,
      quote: {
        ...asset.quote,
        cardmarket: mapping.quote.cardmarket,
      },
      change: {
        ...asset.change,
        cardmarket: {
          '1D': percentAgainst(trend, mapping.pricing.cardmarket.average1Day),
          '1W': percentAgainst(trend, mapping.pricing.cardmarket.average7Days),
          '1M': percentAgainst(trend, mapping.pricing.cardmarket.average30Days),
        },
      },
      pricing: {
        ...asset.pricing,
        cardmarket: {
          ...asset.pricing?.cardmarket,
          ...mapping.pricing.cardmarket,
        },
        usMarket: asset.pricing?.usMarket ?? { market: null, inventory: null },
      },
    };
  });
}
